请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-011

=== 用户原始指令 (query.txt) ===
睡前听书任务卡,深色舞台风,左边信息区显示书名,右边勾选是否听完,横排排列多个待办,带'今晚还需30分钟'这种动态数字,点跳到运动健康,睡眠氛围的环境渐变,文字图标

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "睡前听书任务卡,深色舞台风,左边信息区显示书名,右边勾选是否听完,横排排列多个待办,带'今晚还需30分钟'这种动态数字,点跳到运动健康,睡眠氛围的环境渐变,文字图标",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/router/sleepDetail"
      }
    }
  ],
  "dataModelSchema": {
    "reading": {
      "remainingText": {
        "type": "string",
        "description": "今晚睡前听书还需要完成的剩余时长展示文本",
        "sampleValue": "今晚还需30分钟"
      },
      "bookName": {
        "type": "string",
        "description": "睡前听书任务当前书名",
        "sampleValue": "银河帝国"
      },
      "finished": {
        "type": "boolean",
        "description": "当前听书任务是否已经听完",
        "sampleValue": false
      },
      "finishedLabel": {
        "type": "string",
        "description": "听书完成状态的短标签",
        "sampleValue": "未听完"
      },
      "taskOneDone": {
        "type": "boolean",
        "description": "第一个睡前待办是否完成",
        "sampleValue": false
      },
      "taskOneLabel": {
        "type": "string",
        "description": "第一个睡前待办的短名称",
        "sampleValue": "听书"
      },
      "taskTwoDone": {
        "type": "boolean",
        "description": "第二个睡前待办是否完成",
        "sampleValue": false
      },
      "taskTwoLabel": {
        "type": "string",
        "description": "第二个睡前待办的短名称",
        "sampleValue": "放松"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠图标 PNG，适合表达睡前、睡眠监督和夜间听书任务的文字图标入口。"
    }
  ]
}

